CREATE TABLE IF NOT EXISTS vision_config(id integer PRIMARY KEY CHECK(id=1),enabled_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vision_runs(id text PRIMARY KEY,measurement_id text NOT NULL REFERENCES metrology_runs(id),revision integer NOT NULL,previous_id text,request_key text UNIQUE,equipment_id text NOT NULL,wafer_id text NOT NULL,source jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,alarm boolean NOT NULL DEFAULT false,acknowledged boolean NOT NULL DEFAULT false,expired boolean NOT NULL DEFAULT false,UNIQUE(measurement_id,revision));
CREATE TABLE IF NOT EXISTS vision_jobs(id text PRIMARY KEY,run_id text NOT NULL REFERENCES vision_runs(id),kind text NOT NULL CHECK(kind IN ('map','surface')),input jsonb NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','completed','failed')),attempts integer NOT NULL DEFAULT 0,lease text,lease_until timestamptz,last_sent timestamptz,result jsonb,failure_reason text,UNIQUE(run_id,kind));
CREATE INDEX IF NOT EXISTS vision_pending ON vision_jobs(state,last_sent) WHERE state IN ('queued','running');
CREATE INDEX IF NOT EXISTS vision_measurement ON vision_runs(measurement_id,revision DESC);
